Component(
  dsl: 1, id: "market/unavailable-aware-list", name: "Availability list", kind: Kind.productCollection,
  description: "Products with a sold-out label on the ones that are unavailable.",
  variants: [Variant(id: "default", label: "Default", build:
    Column(gap: Space.sm, children: [ForEach(items: options.products, as: "p", child: Row(gap: Space.sm, crossAxisAlignment: CrossAxisAlignment.center, children: [
      Expanded(child: Text(child: p.name, color: p.is_available ? Color.text : Color.textMuted)),
      If(condition: p.is_available, then: Text(child: formatMoney(p.display_price_cents), weight: FontWeight.semibold), else: Badge(label: "Sold out", tone: Tone.danger))
    ]))])
  )], options: [DataOption(name: "products", type: Product, list: true, required: true)],
)
